package com.way2jobs.scraper;
import com.way2jobs.scraper.config.ScraperProperties; import com.way2jobs.scraper.model.ScrapedJob; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.*; import java.time.format.*; import java.util.*;
@Service @RequiredArgsConstructor public class ScraperValidationService {private final ScraperProperties props; public record ValidationResult(ScrapedJob job,String reason){} public ValidationResult validate(ScrapedJob j){if(j.getTitle()==null||j.getTitle().trim().length()<10)return new ValidationResult(null,"title too short");j.setTitle(j.getTitle().trim());if(blank(j.getNotificationUrl()))j.setNotificationUrl(j.getApplyUrl());if(blank(j.getApplyUrl()))j.setApplyUrl(j.getNotificationUrl());if(blank(j.getNotificationUrl())||blank(j.getApplyUrl()))return new ValidationResult(null,"no usable URL");if(!http(j.getNotificationUrl())||!http(j.getApplyUrl()))return new ValidationResult(null,"invalid URL");LocalDate date=parseDate(j.getLastDateRaw());if(props.isSkipExpired()&&date!=null&&date.isBefore(LocalDate.now()))return new ValidationResult(null,"expired");j.setLastDateRaw(date==null?null:date.toString());j.setVacanciesRaw(parseVacancies(j.getVacanciesRaw()));j.setQualification(truncate(j.getQualification(),100));j.setSalary(truncate(j.getSalary(),100));j.setLocation(truncate(j.getLocation(),100));j.setTitle(truncate(j.getTitle(),255));return new ValidationResult(j,null);} public LocalDate parseDate(String v){if(blank(v))return null;for(String p:List.of("dd-MM-yyyy","dd/MM/yyyy","dd.MM.yyyy","yyyy-MM-dd","dd MMM yyyy","dd MMMM yyyy","MMM dd, yyyy")){try{return LocalDate.parse(v.trim(),DateTimeFormatter.ofPattern(p,Locale.ENGLISH));}catch(DateTimeParseException ignored){}}return null;}private String parseVacancies(String v){try{return v==null?null:String.valueOf(Integer.parseInt(v.replaceAll("[^0-9]","")));}catch(Exception e){return null;}}private boolean blank(String v){return v==null||v.isBlank();}private boolean http(String v){return v.startsWith("http://")||v.startsWith("https://");}private String truncate(String v,int n){return v==null?null:v.length()>n?v.substring(0,n):v;}}
